// Each class's own crest (drawn in code, in brawl-looks.js and the class packs) stays underneath as the fallback for a
// browser without Path2D, which is also what the tests run on.
(function(){
  if(typeof LOOKS==='undefined')return;
  const made={};
  for(const key of Object.keys(EMBLEMS)){
    const E=EMBLEMS[key],L=LOOKS[key]||(LOOKS[key]={}),old=L.crest;
    L.crest=function(fg,bg){
      if(typeof Path2D==='undefined'){if(old)old.call(this,fg,bg);return}
      const p=made[key]||(made[key]=new Path2D(E.d)),k=(E.k||1)*1.5/512;
      g.translate(E.x||0,E.y||0);g.scale(k,k);g.translate(-256,-256);
      g.fillStyle=fg;g.fill(p);
    };
  }
})();
